{"path": "solution.py", "content": "def validate_isbn10(s):
    """'0-306-40615-2' -> True."""
    # Remove all dashes
    cleaned = s.replace('-', '')

    # Must be exactly 10 characters
    if len(cleaned) != 10:
        return False

    # Check each character
    total = 0
    for i in range(10):
        char = cleaned[i]
        if i < 9:
            # First 9 must be digits
            if not char.isdigit():
                return False
            digit = int(char)
        else:
            # Last can be digit or 'X'
            if char.isdigit():
                digit = int(char)
            elif char == 'X':
                digit = 10
            else:
                return False

        # Weighted sum: (i+1) * digit
        total += (i + 1) * digit

    # Must be divisible by 11
    return total % 11 == 0"}

