    """'0-306-40615-2' -> True."""
    # Remove dashes
    cleaned = s.replace('-', '')

    # Must be exactly 10 characters
    if len(cleaned) != 10:
        return False

    # First 9 must be digits
    for i in range(9):
        if not cleaned[i].isdigit():
            return False

    # Last character must be digit or 'X'
    last_char = cleaned[9]
    if not (last_char.isdigit() or last_char == 'X'):
        return False

    # Calculate weighted sum: (i+1) * digit_value for i=0..9
    total = 0
    for i in range(10):
        if i == 9 and cleaned[i] == 'X':
            digit_value = 10
        else:
            digit_value = int(cleaned[i])
        total += (i + 1) * digit_value

    # Sum must be divisible by 11
    return total % 11 == 0"}

