        # First or last word: always capitalize
        if i == 0 or i == n - 1:
            result.append(word.capitalize())
        elif word.lower() in small_words:
            # Small word in the middle: keep lowercase
            result.append(word.lower())
        else:
            # Other words: title case
            result.append(word.capitalize())

    return ' '.join(result)"}

