def validate_isbn10(s):
    """Validate ISBN-10: exactly 10 chars (ignoring dashes), first 9 digits, last digit or 'X', weighted sum divisible by 11."""
    # Remove all dashes
    cleaned = s.replace('-', '')

    # Must be exactly 10 characters
    if len(cleaned) != 10:
        return False

    # Check each character
    digits = []
    for i, c in enumerate(cleaned):
        if i < 9:
            # First 9 must be digits
            if not c.isdigit():
                return False
            digits.append(int(c))
        else:
            # Last character can be digit or 'X'
            if c == 'X':
                digits.append(10)
            elif c.isdigit():
                digits.append(int(c))
            else:
                return False

    # Calculate weighted sum: (i+1) * digit for i=0..9
    weighted_sum = sum((i + 1) * digits[i] for i in range(10))

    # Must be divisible by 11
    return weighted_sum % 11 == 0

