def smart_title(s):
    """'the war of the worlds' -> 'The War of the Worlds'.

    Title-case every word, except that small words (a, an, the, of, in,
    on, to, for) stay lowercase.  The first and last words are always
    capitalized.  Words are separated by spaces.
    """
    if not s:
        return s

    # Split on single spaces so that the original spacing (including
    # leading/trailing/repeated spaces) is preserved on the way out.
    words = s.split(" ")

    # Indices of the actual (non-empty) words.
    word_indices = [i for i, w in enumerate(words) if w]
    if not word_indices:
        return s

    first = word_indices[0]
    last = word_indices[-1]

    result = []
    for i, word in enumerate(words):
        if not word:
            result.append(word)
        elif i == first or i == last:
            # First and last words are always capitalized.
            result.append(word.capitalize())
        elif word.lower() in SMALL_WORDS:
            # Small words stay lowercase.
            result.append(word.lower())
        else:
            result.append(word.capitalize())

    return " ".join(result)
"}

