    """'0-306-40615-2' -> True."""
    if not isinstance(s, str):
        return False

    # Dashes may appear anywhere and are ignored.
    t = s.replace("-", "")

    # Exactly 10 significant characters.
    if len(t) != 10:
        return False

    total = 0
    for i in range(10):
        ch = t[i]
        if "0" <= ch <= "9":
            val = ord(ch) - ord("0")
        elif i == 9 and ch == "X":
            # 'X' is only allowed as the check character and is worth 10.
            val = 10
        else:
            return False
        total += (i + 1) * val

    return total % 11 == 0
"}

