def smart_title(s):
    """'the war of the worlds' -> 'The War of the Worlds'.

    Title-case the string, except small words (a, an, the, of, in, on,
    to, for) stay lowercase. The first and last words are always
    capitalized. Words are space-separated.
    """
    if not s:
        return s

    words = s.split(" ")

    # Indices of the first and last non-empty words (so that leading or
    # trailing spaces don't shift which word counts as first/last).
    non_empty = [i for i, w in enumerate(words) if w]
    first = non_empty[0] if non_empty else -1
    last = non_empty[-1] if non_empty else -1

    result = []
    for i, word in enumerate(words):
        if not word:
            # Preserve runs of consecutive spaces / empty segments.
            result.append(word)
            continue

        lower = word.lower()
        if lower in SMALL_WORDS and i != first and i != last:
            # Interior small word: stays lowercase.
            result.append(lower)
        else:
            # Title case: first letter uppercase, remainder lowercase.
            result.append(lower.capitalize())

    return " ".join(result)
"}

