def validate_isbn10(s):
    """Validate an ISBN-10 string; dashes are ignored.

    '0-306-40615-2' -> True.
    """
    if not isinstance(s, str):
        return False

    # Dashes may appear anywhere and are ignored.
    cleaned = s.replace('-', '')

    # Must be exactly 10 characters after removing dashes.
    if len(cleaned) != 10:
        return False

    total = 0
    for i, ch in enumerate(cleaned):
        if '0' <= ch <= '9':
            value = ord(ch) - ord('0')
        elif ch == 'X' and i == 9:
            # Only the final character may be 'X', worth 10.
            value = 10
        else:
            # Invalid character, or 'X' in a non-final position.
            return False
        total += (i + 1) * value

    return total % 11 == 0

