{"path": "solution.py", "content": "def smart_title(s):
    """Title-case s, keeping small words lowercase except first/last word.

    Small words: a, an, the, of, in, on, to, for.
    The first and last words are always capitalized.
    Words are space-separated.
    """
    SMALL_WORDS = {"a", "an", "the", "of", "in", "on", "to", "for"}

    if not s:
        return s

    # Split on single spaces so original spacing structure is preserved.
    tokens = s.split(" ")

    # Indices of the non-empty tokens (the actual words).
    word_indices = [i for i, t in enumerate(tokens) if t != ""]
    if not word_indices:
        return s

    first_idx = word_indices[0]
    last_idx = word_indices[-1]

    def title_case(word):
        return word[0].upper() + word[1:].lower()

    result = []
    for i, tok in enumerate(tokens):
        if tok == "":
            result.append("")
        elif i == first_idx or i == last_idx:
            # First and last words are always capitalized.
            result.append(title_case(tok))
        elif tok.lower() in SMALL_WORDS:
            # Small words stay lowercase.
            result.append(tok.lower())
        else:
            result.append(title_case(tok))

    return " ".join(result)
"}

